T0=time.time()
sh("python -c \"import torch;print(torch.__version__,torch.cuda.is_available(),torch.cuda.get_device_name(0) if torch.cuda.is_available() else '',torch.cuda.get_arch_list() if torch.cuda.is_available() else '')\"")
sh("pip -q install --no-deps omnivoice webdataset tensorboardx pydub num2words faster-whisper ctranslate2 onnxruntime av tokenizers")
